window.BOSS_KB_FILES = ["boss_kb.pl","boss_derive.pl","boss_rules.pl","boss_infer.pl","boss_advice.pl"];
window.BOSS_KB = {"boss_kb.pl":"% ============================================================\n% B0SS - Business Opportunity Screening System\n% boss_kb.pl - Fixed domain knowledge base\n%\n% 25 unconditional facts, transcribed verbatim from SRS section 5.\n% These never change between assessments. Session facts asserted\n% from the user's answers live in working memory, not here.\n%\n% Count: 7 supported_business + 3 safe_funding + 3 dangerous_funding\n%      + 4 demand_level + 4 cash_cycle_type + 4 legal_value = 25\n% ============================================================\n\n% --- Business types B0SS is allowed to screen (7) ---\nsupported_business(service).\nsupported_business(retail).\nsupported_business(online).\nsupported_business(education).\nsupported_business(professional_service).\nsupported_business(food).\nsupported_business(owner_trade).\n\n% --- Funding sources that do not endanger the household (3) ---\nsafe_funding(own_savings).\nsafe_funding(family_interest_free).\nsafe_funding(formal_affordable).\n\n% --- Funding sources that trigger the R10 absolute override (3) ---\ndangerous_funding(informal_high_interest).\ndangerous_funding(pawned_asset).\ndangerous_funding(home_secured_loan).\n\n% --- Strength of evidence that somebody will actually pay (4) ---\ndemand_level(none).\ndemand_level(anecdotal).\ndemand_level(observed).\ndemand_level(validated).\n\n% --- How money moves in and out of the business (4) ---\ncash_cycle_type(advance_payment).\ncash_cycle_type(on_delivery).\ncash_cycle_type(long_credit).\ncash_cycle_type(heavy_stock).\n\n% --- Licensing / legal position (4) ---\nlegal_value(none_required).\nlegal_value(routine).\nlegal_value(unknown).\nlegal_value(blocking).\n","boss_derive.pl":"% ============================================================\n% B0SS - boss_derive.pl\n% Working-memory declarations and derived values.\n%\n% SRS section 4.2: these are CALCULATED from user answers and are\n% never asked as separate questions.\n%\n% The clauses in this file are derivation parameters, NOT domain\n% facts: the 25 knowledge-base facts of SRS section 5 remain\n% exactly 25. See DECISIONS.md, decision 1.\n% ============================================================\n\n% --- Session facts, asserted by the interface (SRS 4.1) ---\n:- dynamic(business_type/1).\n:- dynamic(venture_type/1).\n:- dynamic(channel_type/1).\n:- dynamic(demand_evidence/1).\n:- dynamic(target_customer/1).\n:- dynamic(repeat_demand/1).\n:- dynamic(price_status/1).\n:- dynamic(owner_experience/1).\n:- dynamic(owner_time/1).\n:- dynamic(reversibility/1).\n:- dynamic(startup_cost/1).\n:- dynamic(monthly_cost/1).\n:- dynamic(capital_available/1).\n:- dynamic(capital_status/1).\n:- dynamic(funding_source/1).\n:- dynamic(stated_rate/1).\n:- dynamic(margin_rate/1).\n:- dynamic(breakeven_months/1).\n:- dynamic(personal_runway/1).\n:- dynamic(cash_cycle/1).\n:- dynamic(competition/1).\n:- dynamic(differentiation/1).\n:- dynamic(dependency/1).\n:- dynamic(legal_status/1).\n\n% ------------------------------------------------------------\n% SRS 4.2 - arithmetic\n% ------------------------------------------------------------\n\n% capital_requirement = startup_cost + (6 x monthly_operating_cost)\ncapital_requirement(C) :-\n    startup_cost(S),\n    monthly_cost(M),\n    C is S + 6 * M.\n\n% funded_months = max(0, capital_available - startup_cost) / monthly_cost\n% Written as a conditional rather than max/2: Tau-Prolog's evaluable\n% functor coverage is thinner than SWI's.\nfunded_months(F) :-\n    capital_available(A),\n    startup_cost(S),\n    monthly_cost(M),\n    M > 0,\n    Spare is A - S,\n    (   Spare > 0\n    ->  F is Spare / M\n    ;   F = 0\n    ).\n\n% survival_gap = funded_months - breakeven_months\nsurvival_gap(G) :-\n    funded_months(F),\n    breakeven_months(B),\n    G is F - B.\n\n% ------------------------------------------------------------\n% Margin: numeric input -> category (decision 1)\n% SRS 3.5 rule of thumb: above 30% retail, above 45% services.\n% ------------------------------------------------------------\n\nmargin_floor(retail, 30).\nmargin_floor(food, 30).\nmargin_floor(service, 45).\nmargin_floor(online, 45).\nmargin_floor(education, 45).\nmargin_floor(professional_service, 45).\nmargin_floor(owner_trade, 45).\n\nmargin_level(L) :-\n    margin_rate(R),\n    business_type(T),\n    margin_floor(T, Floor),\n    Strong is Floor + 15,\n    (   R >= Strong ->  L = strong\n    ;   R >= Floor  ->  L = adequate\n    ;                   L = low\n    ).\n\n% ------------------------------------------------------------\n% Cost of the money funding the business (needed by R11).\n% Own savings and interest-free family money cost nothing.\n% Any borrowed source uses the rate the user stated; if no rate\n% is known this simply fails, so R11 cannot fire on a guess\n% (NFR-Robustness: the system must not invent defaults).\n% ------------------------------------------------------------\n\nfree_capital(own_savings).\nfree_capital(family_interest_free).\n\neffective_funding_cost(0) :-\n    funding_source(S),\n    free_capital(S).\neffective_funding_cost(R) :-\n    funding_source(S),\n    \\+ free_capital(S),\n    stated_rate(R).\n\n% ------------------------------------------------------------\n% Domain validation and scope - what the type facts in boss_kb.pl\n% are for. Every categorical answer must be a value this knowledge\n% base recognises, and the business itself must be one B0SS is\n% allowed to screen (SRS section 2).\n% ------------------------------------------------------------\n\nknown_value(business_type(T))   :- supported_business(T).\nknown_value(demand_evidence(unknown)).\nknown_value(demand_evidence(D)) :- demand_level(D).\nknown_value(cash_cycle(C))      :- cash_cycle_type(C).\nknown_value(legal_status(L))    :- legal_value(L).\nknown_value(funding_source(F))  :- safe_funding(F).\nknown_value(funding_source(F))  :- dangerous_funding(F).\n\nchecked_input(demand_evidence(_)).\nchecked_input(cash_cycle(_)).\nchecked_input(legal_status(_)).\nchecked_input(funding_source(_)).\n\n% An answer this knowledge base does not recognise. The system must\n% not reason from a value it has no facts about.\nunrecognised(Name) :-\n    checked_input(Fact),\n    call(Fact),\n    \\+ known_value(Fact),\n    functor(Fact, Name, _).\n\n% SRS section 2: B0SS must not evaluate businesses outside the\n% supported list - pharmaceuticals, finance, franchises and the rest\n% need specialist judgement these rules do not contain.\nin_scope :-\n    business_type(T),\n    supported_business(T).\n\nout_of_scope(T) :-\n    business_type(T),\n    \\+ supported_business(T).\n\n% ------------------------------------------------------------\n% Critical unknowns - SRS 9.1 step 2 (decision 4)\n% Demand, price, capital and legal status are the four inputs\n% that block a positive answer when they are not known.\n% ------------------------------------------------------------\n\ncritical_unknown(demand) :-\n    demand_evidence(unknown).\ncritical_unknown(price) :-\n    price_status(P),\n    member(P, [assumed, unknown]).\ncritical_unknown(capital) :-\n    capital_status(unknown).\ncritical_unknown(legal) :-\n    legal_status(unknown).\n","boss_rules.pl":"% ============================================================\n% B0SS - boss_rules.pl\n% The 25 expert IF-THEN rules (SRS section 7).\n%\n% Representation is the one documented in SRS 7.1:\n%     rule(Id, Conclusion, CF) :- Evidence.\n%\n% Where the expert stated two outcomes for one rule (a conclusion\n% plus a validation_gap or red_flag entry) the conclusion is an\n% and/2 term. concludes/3 in boss_infer.pl unfolds it, so rule/3\n% keeps the arity and shape the SRS shows.\n%\n% CF expresses the expert's belief in the rule conclusion when its\n% evidence is present. It is NOT a probability of business success.\n% ============================================================\n\n% Dynamic only so the knowledge editor's checks (boss_kbcheck.pl) can\n% read rule bodies with clause/2: Tau-Prolog refuses clause/2 on\n% static code. Nothing asserts or retracts rules at run time.\n:- dynamic(rule/3).\n\n% ---------- Market attractiveness ----------\n\n% R01 - strongest practical evidence of a repeatable market.\nrule(r01, market_attractiveness(high), 0.8) :-\n    demand_evidence(validated),\n    repeat_demand(recurring).\n\n% R02 - real evidence plus a reachable customer group.\n% Concludes 'moderate': R01 already covers the 'high' case.\nrule(r02, market_attractiveness(moderate), 0.6) :-\n    demand_evidence(D),\n    member(D, [observed, validated]),\n    target_customer(specific).\n\n% R03 - interest or encouragement is not willingness to pay.\nrule(r03, and(market_attractiveness(low), validation_gap(test_demand)), -0.8) :-\n    demand_evidence(D),\n    member(D, [none, anecdotal]).\n\n% R04 - financial conclusions are weak until the price is checked.\nrule(r04, validation_gap(validate_price), -0.4) :-\n    price_status(assumed).\n\n% ---------- Competitive position ----------\n\n% R05 - a small entrant cannot rely on an undifferentiated price fight.\nrule(r05, competitive_position(weak), -0.8) :-\n    competition(many_strong),\n    differentiation(D),\n    member(D, [none, price_only]).\n\n% R06 - a specific reason to choose the business can offset crowding.\nrule(r06, competitive_position(strong), 0.6) :-\n    competition(C),\n    member(C, [few, many_weak]),\n    differentiation(strong).\n\n% ---------- Financial readiness ----------\n\n% R07 - funded through startup and six months from a safe source.\nrule(r07, financial_readiness(ready), 0.8) :-\n    capital_available(A),\n    capital_requirement(R),\n    A >= R,\n    funding_source(S),\n    safe_funding(S).\n\n% R08 - underfunded; the plan should be reduced or delayed.\n% Concludes 'marginal': R09 already covers the severe case.\nrule(r08, financial_readiness(marginal), -0.6) :-\n    capital_available(A),\n    capital_requirement(R),\n    Half is 0.5 * R,\n    A >= Half,\n    A < R.\n\n% R09 - unlikely to stay open long enough to test the market.\nrule(r09, and(overall_risk(high), red_flag(severe_underfunding)), -0.8) :-\n    capital_available(A),\n    capital_requirement(R),\n    Half is 0.5 * R,\n    A < Half.\n\n% ---------- Absolute overrides ----------\n\n% R10 - risky funding can endanger the household.\nrule(r10, recommendation(not_recommended), -1.0) :-\n    funding_source(S),\n    dangerous_funding(S).\n\n% R11 - each sale destroys value at the financing cost.\nrule(r11, recommendation(not_recommended), -1.0) :-\n    margin_rate(M),\n    effective_funding_cost(C),\n    M < C.\n\n% ---------- Margin, cash cycle and survival ----------\n\n% R12 - healthy margin and early cash collection make mistakes survivable.\nrule(r12, financial_readiness(ready), 0.6) :-\n    margin_level(L),\n    member(L, [adequate, strong]),\n    cash_cycle(C),\n    member(C, [advance_payment, on_delivery]).\n\n% R13 - money is tied up before cash returns to the business.\nrule(r13, overall_risk(high), -0.6) :-\n    cash_cycle(C),\n    member(C, [long_credit, heavy_stock]),\n    \\+ holds_upto(1, financial_readiness(ready)).\n\n% R14 - expected to run out of funded time before break-even.\nrule(r14, and(overall_risk(high), survival_runway(insufficient)), -0.8) :-\n    breakeven_months(B),\n    funded_months(F),\n    B > F.\n\n% ---------- Owner readiness ----------\n\n% R15 - hands-on experience reduces operating and quality-control errors.\nrule(r15, owner_readiness(strong), 0.8) :-\n    owner_experience(direct).\n\n% R16 - learning is expensive when the commitment cannot be reversed.\nrule(r16, owner_readiness(weak), -0.8) :-\n    owner_experience(none),\n    reversibility(low).\n\n% R17 - low-cost reversible starts allow the owner to learn safely.\nrule(r17, owner_readiness(adequate), 0.4) :-\n    owner_experience(none),\n    reversibility(high).\n\n% ---------- Operations ----------\n\n% R18 - a walk-in business must be available during customer hours.\nrule(r18, operational_readiness(not_ready), -0.6) :-\n    owner_time(insufficient),\n    channel_type(walk_in).\n\n% R19 - one customer, supplier, person or platform is a single point of failure.\nrule(r19, and(overall_risk(high), red_flag(concentration)), -0.6) :-\n    dependency(high).\n\n% R20 - household pressure forces damaging short-term business decisions.\nrule(r20, and(overall_risk(high), red_flag(household_exposure)), -0.8) :-\n    personal_runway(P),\n    P < 3,\n    breakeven_months(B),\n    B > 6.\n\n% R21 - the business cannot legally operate in the proposed form.\nrule(r21, recommendation(not_recommended), -1.0) :-\n    legal_status(blocking).\n\n% ---------- Final recommendation rules ----------\n\n% R22 - report insufficient basis rather than guess.\n% \\+ \\+ gives exactly one solution however many unknowns exist.\nrule(r22, recommendation(further_validation_required), 0.0) :-\n    \\+ \\+ critical_unknown(_).\n\n% R23 - nothing in the screening currently argues against detailed planning.\nrule(r23, recommendation(proceed), 0.8) :-\n    \\+ absolute_override,\n    \\+ critical_unknown(_),\n    core_positive,\n    holds(financial_readiness(ready)),\n    holds(owner_readiness(O)),\n    member(O, [adequate, strong]),\n    \\+ weakness(_).\n\n% R24 - the opportunity may continue only with stated mitigations.\nrule(r24, recommendation(proceed_with_caution), 0.6) :-\n    \\+ absolute_override,\n    \\+ critical_unknown(_),\n    core_positive,\n    weakness_count(N),\n    N > 0,\n    N =< 2.\n\n% R25 - the current scale/model should change before reassessment.\nrule(r25, recommendation(not_recommended_in_this_form), -0.8) :-\n    \\+ absolute_override,\n    \\+ critical_unknown(_),\n    severe_risk_count(N),\n    N >= 2.\n","boss_infer.pl":"% ============================================================\n% B0SS - boss_infer.pl\n% Inference control: rule stratification, severity tables and the\n% SRS section 9.1 priority ladder.\n%\n% Backward chaining is the query strategy (SRS section 4). Rules\n% are grouped into levels so that a rule which asks what another\n% rule concluded can never re-enter its own body:\n%\n%   level 1  intermediate conclusions drawn straight from facts\n%   level 2  intermediate conclusions that consult level 1 (R13)\n%   level 3  recommendation rules (overrides and final verdicts)\n%\n% holds/1 exposes levels 1-2 only, so the final rules can read the\n% intermediate picture while remaining outside it.\n% ============================================================\n\nrule_level(r01, 1). rule_level(r02, 1). rule_level(r03, 1).\nrule_level(r04, 1). rule_level(r05, 1). rule_level(r06, 1).\nrule_level(r07, 1). rule_level(r08, 1). rule_level(r09, 1).\nrule_level(r12, 1). rule_level(r14, 1). rule_level(r15, 1).\nrule_level(r16, 1). rule_level(r17, 1). rule_level(r18, 1).\nrule_level(r19, 1). rule_level(r20, 1).\nrule_level(r13, 2).\nrule_level(r10, 3). rule_level(r11, 3). rule_level(r21, 3).\nrule_level(r22, 3). rule_level(r23, 3). rule_level(r24, 3).\nrule_level(r25, 3).\n\n% Unfold an and/2 conclusion into its individual conclusions.\nunfold(and(A, B), C) :- !, ( unfold(A, C) ; unfold(B, C) ).\nunfold(C, C).\n\n% A rule fires when its body succeeds. Id is always bound before\n% rule/3 is called, so only that one clause is ever executed.\n%\n% The \\+ \\+ gives exactly one solution per rule. Without it a rule whose\n% body consults holds/1 succeeds once per rule that supports the same\n% conclusion - R23 yields two identical solutions when both R07 and R12\n% conclude financial_readiness(ready).\nfires(Id) :-\n    rule_level(Id, _),\n    \\+ \\+ rule(Id, _, _).\n\n% What an applicable rule up to level L concludes.\nholds_upto(L, C) :-\n    rule_level(Id, RL),\n    RL =< L,\n    rule(Id, Concl, _),\n    unfold(Concl, C).\n\n% Intermediate conclusions visible to the final recommendation rules.\nholds(C) :- holds_upto(2, C).\n\n% ------------------------------------------------------------\n% Severity tables (decision 3)\n% These make the SRS's prose thresholds - \"at most two manageable\n% weaknesses\", \"two or more severe unmitigated risks\" - countable,\n% and keep them editable in one place.\n% ------------------------------------------------------------\n\nsevere_risk(no_market)           :- holds(market_attractiveness(low)).\nsevere_risk(owner_unready)       :- holds(owner_readiness(weak)).\nsevere_risk(competitive_weak)    :- holds(competitive_position(weak)).\nsevere_risk(severe_underfunding) :- holds(red_flag(severe_underfunding)).\nsevere_risk(concentration)       :- holds(red_flag(concentration)).\nsevere_risk(household_exposure)  :- holds(red_flag(household_exposure)).\nsevere_risk(survival_runway)     :- holds(survival_runway(insufficient)).\n\nweakness(W) :- severe_risk(W).\nweakness(financial_marginal)     :- holds(financial_readiness(marginal)).\nweakness(operations_not_ready)   :- holds(operational_readiness(not_ready)).\nweakness(cash_cycle_slow) :-\n    holds(overall_risk(high)),\n    cash_cycle(C),\n    member(C, [long_credit, heavy_stock]).\n\nsevere_risk_count(N) :-\n    findall(R, severe_risk(R), L0),\n    sort(L0, L),\n    length(L, N).\n\nweakness_count(N) :-\n    findall(W, weakness(W), L0),\n    sort(L0, L),\n    length(L, N).\n\n% The core case the expert checks before any softer factor.\ncore_positive :-\n    \\+ \\+ ( holds(market_attractiveness(M)), member(M, [high, moderate]) ),\n    \\+ holds(owner_readiness(weak)),\n    \\+ holds(red_flag(severe_underfunding)).\n\n% ------------------------------------------------------------\n% Absolute overrides - SRS 8.1: R10, R11 and R21 bypass all\n% positive evidence.\n% ------------------------------------------------------------\n\nabsolute_override :-\n    member(Id, [r10, r11, r21]),\n    rule(Id, _, _),\n    !.\n\n% ------------------------------------------------------------\n% SRS 9.1 priority order\n% The verdict carries the CF of the rule that decided it (SRS 8.1:\n% \"the final recommendation rule has its own CF\"), so a CF edited in\n% boss_rules.pl is the CF the user sees. Only the two exits no rule\n% covers - out of scope and the fall-through - state 0.0 here.\n% ------------------------------------------------------------\n\nrecommendation(Rec, CF) :-\n    (   out_of_scope(_)\n    ->  Rec = out_of_scope,                  CF = 0.0\n    ;   absolute_override\n    ->  Rec = not_recommended,               override_cf(CF)\n    ;   critical_unknown(_)\n    ->  Rec = further_validation_required,   rule_cf(r22, CF)\n    ;   fires(r23)\n    ->  Rec = proceed,                       rule_cf(r23, CF)\n    ;   fires(r24)\n    ->  Rec = proceed_with_caution,          rule_cf(r24, CF)\n    ;   fires(r25)\n    ->  Rec = not_recommended_in_this_form,  rule_cf(r25, CF)\n    ;   Rec = further_validation_required,   CF = 0.0\n    ).\n\nrule_cf(Id, CF) :-\n    once(rule(Id, _, CF)).\n\n% Several overrides may fire; the strongest (most negative) decides.\noverride_cf(CF) :-\n    findall(C, ( override_fired(Id), rule_cf(Id, C) ), Cs),\n    sort(Cs, [CF|_]).\n\n% ------------------------------------------------------------\n% The path through the SRS 9.1 ladder that produced this answer.\n% Returned as a list of d(Gate, pass|exit, Detail) so the interface can\n% draw the route actually taken. This is derived from the same checks\n% recommendation/2 makes - it is not a hand-drawn picture of them.\n% ------------------------------------------------------------\n\noverride_fired(Id) :-\n    member(Id, [r10, r11, r21]),\n    rule(Id, _, _).\n\ndecision_path(P) :-\n    (   out_of_scope(T)\n    ->  P = [d(scope, exit, T)]\n    ;   S = d(scope, pass, ok),\n        (   absolute_override\n        ->  findall(I, override_fired(I), Os),\n            P = [S, d(override, exit, Os)]\n        ;   O = d(override, pass, []),\n            (   critical_unknown(_)\n            ->  findall(U, critical_unknown(U), Us0), sort(Us0, Us),\n                P = [S, O, d(unknowns, exit, Us)]\n            ;   U = d(unknowns, pass, []),\n                weakness_count(W),\n                severe_risk_count(V),\n                (   fires(r23)\n                ->  P = [S, O, U, d(proceed, exit, W)]\n                ;   Pr = d(proceed, pass, W),\n                    (   fires(r24)\n                    ->  P = [S, O, U, Pr, d(caution, exit, W)]\n                    ;   C = d(caution, pass, W),\n                        (   fires(r25)\n                        ->  P = [S, O, U, Pr, C, d(in_this_form, exit, V)]\n                        ;   P = [S, O, U, Pr, C, d(in_this_form, pass, V),\n                                 d(insufficient, exit, 0)]\n                        )\n                    )\n                )\n            )\n        )\n    ).\n\n% ------------------------------------------------------------\n% Explanation support - SRS section 10 / FR-08 / FR-09\n% ------------------------------------------------------------\n\n% Every rule that fired, with its conclusion and CF, strongest first.\ntrace(Trace) :-\n    findall(t(Abs, Id, Concl, CF),\n            ( fires(Id), rule(Id, Concl, CF), Abs is -abs(CF) ),\n            L0),\n    sort(L0, L1),\n    findall(fired(Id, Concl, CF), member(t(_, Id, Concl, CF), L1), Trace).\n\npositives(Top) :-\n    trace(T),\n    findall(fired(Id, C, CF), ( member(fired(Id, C, CF), T), CF > 0 ), L),\n    first_n(3, L, Top).\n\nconcerns(Top) :-\n    trace(T),\n    findall(fired(Id, C, CF), ( member(fired(Id, C, CF), T), CF < 0 ), L),\n    first_n(3, L, Top).\n\nmissing(M) :-\n    findall(U, critical_unknown(U), L0),\n    sort(L0, M).\n\ngaps(G) :-\n    findall(Item, holds(validation_gap(Item)), L0),\n    sort(L0, G).\n\nfirst_n(0, _, []) :- !.\nfirst_n(_, [], []) :- !.\nfirst_n(N, [H|T], [H|R]) :- N1 is N - 1, first_n(N1, T, R).\n\n% ------------------------------------------------------------\n% Single entry point queried by the interface.\n% ------------------------------------------------------------\n\nassess(assessment(Rec, CF, Pos, Con, Missing, Gaps, Trace, Money, Scope, Concl, Path)) :-\n    scope(Scope),\n    conclusions(Concl),\n    decision_path(Path),\n    recommendation(Rec, CF),\n    positives(Pos),\n    concerns(Con),\n    missing(Missing),\n    gaps(Gaps),\n    trace(Trace),\n    money(Money).\n\n% The six intermediate conclusions of SRS section 6, for the summary\n% panel. Each is whatever the applicable rules concluded.\nconclusion(market,     V) :- holds(market_attractiveness(V)).\nconclusion(competition,V) :- holds(competitive_position(V)).\nconclusion(finance,    V) :- holds(financial_readiness(V)).\nconclusion(owner,      V) :- holds(owner_readiness(V)).\nconclusion(operations, V) :- holds(operational_readiness(V)).\nconclusion(risk,       V) :- holds(overall_risk(V)).\n\nconclusions(L) :-\n    findall(c(K, V), conclusion(K, V), L0),\n    sort(L0, L).\n\n% Scope and input validation (SRS section 2).\nscope(scope(State, Bad)) :-\n    ( out_of_scope(T) -> State = out_of_scope(T)\n    ; in_scope        -> State = ok\n    ;                    State = ok\n    ),\n    findall(N, unrecognised(N), Bad0),\n    sort(Bad0, Bad).\n\n% Visible arithmetic for the explanation (SRS section 10).\nmoney(money(Req, Funded, Gap)) :-\n    ( capital_requirement(R) -> Req = R ; Req = unknown ),\n    ( funded_months(F)       -> Funded = F ; Funded = unknown ),\n    ( survival_gap(G)        -> Gap = G ; Gap = unknown ).\n","boss_advice.pl":"% ============================================================\n% B0SS - boss_advice.pl\n% Presentation knowledge: what each rule means in plain business\n% language, and the specific next action for every concern\n% (SRS section 10). Kept in the knowledge base rather than the\n% interface so it can be edited without touching the UI (FR-11).\n% ============================================================\n\n% ---------- Plain-language reading of each rule ----------\n\nrule_text(r01, 'Repeat customers already pay your price.').\nrule_text(r02, 'Observed demand, and you know the customer.').\nrule_text(r03, 'Nobody has paid yet; interest is not demand.').\nrule_text(r04, 'Your price is untested against the market.').\nrule_text(r05, 'Strong competitors, nothing that sets you apart.').\nrule_text(r06, 'A clear edge offsets the competition.').\nrule_text(r07, 'Capital covers startup plus 6 months, from a safe source.').\nrule_text(r08, 'You have most of the money, not all of it.').\nrule_text(r09, 'You have under half the money needed.').\nrule_text(r10, 'The funding could take the household down with it.').\nrule_text(r11, 'Margin is below the cost of the funding.').\nrule_text(r12, 'Healthy margin and early cash.').\nrule_text(r13, 'Cash goes out well before it comes in.').\nrule_text(r14, 'Funded months run out before break-even.').\nrule_text(r15, 'You have done this work yourself.').\nrule_text(r16, 'No hands-on experience, no cheap way to stop.').\nrule_text(r17, 'No experience, but a small, reversible start.').\nrule_text(r18, 'A walk-in business needs you there in customer hours.').\nrule_text(r19, 'One customer, supplier, person or platform can end it.').\nrule_text(r20, 'The household runs out of money before the business pays.').\nrule_text(r21, 'It cannot legally operate in this form.').\nrule_text(r22, 'Something critical is unknown, so no positive answer.').\nrule_text(r23, 'Nothing argues against detailed planning.').\nrule_text(r24, 'The core case holds; weaknesses need mitigation.').\nrule_text(r25, 'Several serious but fixable problems.').\n\n% ---------- A specific next action for every concern ----------\n\nnext_action(r03, 'Get one real payment or signed commitment at your price.').\nnext_action(r04, 'Ask 3 likely customers what they pay; check 2 competitors'' prices.').\nnext_action(r05, 'Name the one reason a customer would switch to you, or change the offer.').\nnext_action(r08, 'Raise the shortfall first, or cut the plan to fit your capital.').\nnext_action(r09, 'Redesign to a version you can fund for six months.').\nnext_action(r10, 'Change the funding or scale: no home-secured or high-interest money.').\nnext_action(r11, 'Recheck margin and interest; if the margin is real, each sale loses money.').\nnext_action(r13, 'Negotiate deposits or faster payment before buying stock.').\nnext_action(r14, 'Cut monthly costs or raise capital until funded months beat break-even.').\nnext_action(r16, 'Work in the trade for a season, or bring in an experienced partner.').\nnext_action(r18, 'Arrange cover for customer hours, or change channel.').\nnext_action(r19, 'Get the dependency in writing and line up a second option.').\nnext_action(r20, 'Keep 3 months of household costs outside the business, or delay.').\nnext_action(r21, 'Confirm the licence position with the authority first.').\n\n% ---------- Missing information -> what to go and find out ----------\n\nunknown_label(demand,  'Whether anyone will pay is untested.').\nunknown_label(price,   'The selling price is unvalidated.').\nunknown_label(capital, 'Your actual capital is not known.').\nunknown_label(legal,   'The licensing position is unknown.').\n\nunknown_action(demand,  'Take one deposit, pre-order or paid trial.').\nunknown_action(price,   'Check the price against real competitors and customers.').\nunknown_action(capital, 'Work out startup and monthly running costs.').\nunknown_action(legal,   'Find out which licences are needed, and if you can get them.').\n\n% SRS section 6 \"validation gap\": critical items that are assumed rather\n% than known. These are the heart of what B0SS is for.\ngap_label(test_demand,    'Demand is untested with money.').\ngap_label(validate_price, 'The selling price is unvalidated.').\n\ngap_action(test_demand,    'Take one deposit, pre-order or paid trial.').\ngap_action(validate_price, 'Check the price against 2 competitors and 3 likely customers.').\n\n% ---------- CF labels, SRS section 8 ----------\n\ncf_label(CF, 'Definitely not')    :- CF =< -0.9.\ncf_label(CF, 'Almost certainly not') :- CF > -0.9, CF =< -0.7.\ncf_label(CF, 'Probably not')      :- CF > -0.7, CF =< -0.5.\ncf_label(CF, 'Maybe not')         :- CF > -0.5, CF =< -0.3.\ncf_label(CF, 'Unknown / insufficient basis') :- CF > -0.3, CF < 0.3.\ncf_label(CF, 'Maybe')             :- CF >= 0.3, CF < 0.5.\ncf_label(CF, 'Probably')          :- CF >= 0.5, CF < 0.7.\ncf_label(CF, 'Almost certainly')  :- CF >= 0.7, CF < 0.9.\ncf_label(CF, 'Definitely')        :- CF >= 0.9.\n\n% ---------- The six intermediate conclusions (SRS section 6) ----------\n\nconclusion_label(market,     'Demand').\nconclusion_label(competition,'Competition').\nconclusion_label(finance,    'Money').\nconclusion_label(owner,      'Owner').\nconclusion_label(operations, 'Operations').\nconclusion_label(risk,       'Risk').\n\nconclusion_word(market, high,     'Strong').\nconclusion_word(market, moderate, 'Moderate').\nconclusion_word(market, low,      'No evidence').\nconclusion_word(competition, strong,   'Defensible').\nconclusion_word(competition, adequate, 'Adequate').\nconclusion_word(competition, weak,     'Exposed').\nconclusion_word(finance, ready,     'Funded').\nconclusion_word(finance, marginal,  'Short').\nconclusion_word(finance, not_ready, 'Not funded').\nconclusion_word(owner, strong,   'Experienced').\nconclusion_word(owner, adequate, 'Learnable').\nconclusion_word(owner, weak,     'Unready').\nconclusion_word(operations, ready,     'Workable').\nconclusion_word(operations, marginal,  'Tight').\nconclusion_word(operations, not_ready, 'Not workable').\nconclusion_word(risk, low,      'Low').\nconclusion_word(risk, moderate, 'Moderate').\nconclusion_word(risk, high,     'High').\nconclusion_word(risk, critical, 'Critical').\n\n% Whether a conclusion reads as positive, mixed or negative. Depends on\n% the dimension: 'high' is good for demand and bad for risk.\nconclusion_tone(market, high, good).      conclusion_tone(market, moderate, warn).\nconclusion_tone(market, low, bad).\nconclusion_tone(competition, strong, good). conclusion_tone(competition, adequate, warn).\nconclusion_tone(competition, weak, bad).\nconclusion_tone(finance, ready, good).    conclusion_tone(finance, marginal, warn).\nconclusion_tone(finance, not_ready, bad).\nconclusion_tone(owner, strong, good).     conclusion_tone(owner, adequate, warn).\nconclusion_tone(owner, weak, bad).\nconclusion_tone(operations, ready, good). conclusion_tone(operations, marginal, warn).\nconclusion_tone(operations, not_ready, bad).\nconclusion_tone(risk, low, good).         conclusion_tone(risk, moderate, warn).\nconclusion_tone(risk, high, bad).         conclusion_tone(risk, critical, bad).\n\n% ---------- The SRS 9.1 decision ladder, in plain words ----------\n\ngate_label(scope,        'Can B0SS screen it?').\ngate_label(override,     'Any deal-breaker?').\ngate_label(unknowns,     'Anything critical unknown?').\ngate_label(proceed,      'Core case clean?').\ngate_label(caution,      'Sound, with fixable weaknesses?').\ngate_label(in_this_form, '2+ serious risks?').\ngate_label(insufficient, 'Not enough to decide.').\n\ngate_detail(override,     'Dangerous funding, margin below funding cost, or a legal blocker.').\ngate_detail(unknowns,     'Demand, price, capital or licensing.').\ngate_detail(proceed,      'Demand, money, owner and operations all hold, with no weakness.').\ngate_detail(caution,      'Core factors positive and at most two weaknesses.').\ngate_detail(in_this_form, 'Serious but correctable - the plan should change first.').\n\ngate_outcome(scope,        out_of_scope).\ngate_outcome(override,     not_recommended).\ngate_outcome(unknowns,     further_validation_required).\ngate_outcome(proceed,      proceed).\ngate_outcome(caution,      proceed_with_caution).\ngate_outcome(in_this_form, not_recommended_in_this_form).\ngate_outcome(insufficient, further_validation_required).\n\n% ---------- Verdict headline text ----------\n\nverdict_text(out_of_scope, 'OUTSIDE WHAT B0SS CAN SCREEN').\nverdict_text(proceed, 'PROCEED').\nverdict_text(proceed_with_caution, 'PROCEED WITH CAUTION').\nverdict_text(further_validation_required, 'FURTHER VALIDATION REQUIRED').\nverdict_text(not_recommended, 'NOT RECOMMENDED').\nverdict_text(not_recommended_in_this_form, 'NOT RECOMMENDED IN THIS FORM').\n\nverdict_blurb(out_of_scope, 'This type needs specialist judgement these rules do not contain.').\nverdict_blurb(proceed, 'Continue to detailed planning. This is not a prediction of success.').\nverdict_blurb(proceed_with_caution, 'The core case is positive, but fix the concerns below before or during launch.').\nverdict_blurb(further_validation_required, 'Something critical is unknown. Check it before deciding.').\nverdict_blurb(not_recommended, 'A blocking condition makes this unacceptable, whatever else is strong.').\nverdict_blurb(not_recommended_in_this_form, 'Change the scale, model, dependency or timing, then assess again.').\n","boss_kbcheck.pl":"% ============================================================\n% B0SS - boss_kbcheck.pl\n% Knowledge-base verification, used by the knowledge editor.\n%\n% A meta-level program: it reads the rules as data through\n% clause/2 and reports anything that would make the knowledge\n% base inconsistent, incomplete or silently inert. It is not part\n% of the inference the user sees, and the assessment page never\n% loads it.\n%\n%   kb_issues(L)   L = sorted list of i(Severity, Code, Subject)\n%                  Severity is error (the editor refuses to save)\n%                  or warning (saved, but shown to the expert).\n%\n% The interface may assert ui_value(Attribute, Value) for every\n% value the questionnaire can produce (web/schema.js). Values\n% the knowledge base itself enumerates come from known_value/1.\n% ============================================================\n\n:- dynamic(ui_value/2).\n:- discontiguous(kb_issue/3).\n\nkb_issues(L) :-\n    findall(i(S, C, X), kb_issue(S, C, X), L0),\n    sort(L0, L).\n\n% ------------------------------------------------------------\n% Reading the rule base as data\n% ------------------------------------------------------------\n\nrule_clause(Id, Concl, CF, Body) :-\n    clause(rule(Id, Concl, CF), Body).\n\nrule_id(Id) :- rule_clause(Id, _, _, _).\n\n% Every simple goal in a rule body. Negation is kept, so a value\n% tested under \\+ is still checked against its domain.\nbody_goal(G, _) :- var(G), !, fail.\nbody_goal((A, B), G)    :- !, ( body_goal(A, G) ; body_goal(B, G) ).\nbody_goal((A ; B), G)   :- !, ( body_goal(A, G) ; body_goal(B, G) ).\nbody_goal((A -> B), G)  :- !, ( body_goal(A, G) ; body_goal(B, G) ).\nbody_goal(\\+ A, G)      :- !, body_goal(A, G).\nbody_goal(call(A), G)   :- !, body_goal(A, G).\nbody_goal(G, G).\n\n% Goals a rule may call that are not defined in the knowledge base.\nbuiltin(member/2).  builtin(memberchk/2). builtin(is/2).\nbuiltin((<)/2).     builtin((>)/2).       builtin((=<)/2).\nbuiltin((>=)/2).    builtin((=:=)/2).     builtin((=\\=)/2).\nbuiltin((=)/2).     builtin((\\=)/2).      builtin((==)/2).\nbuiltin((\\==)/2).   builtin(true/0).      builtin(fail/0).\nbuiltin(length/2).  builtin(findall/3).   builtin(sort/2).\nbuiltin(between/3). builtin(number/1).    builtin(atom/1).\n\n% A session attribute is one the interface asserts: boss_derive.pl\n% declares each of them dynamic (SRS 4.1).\nsession_attribute(A) :-\n    atom(A),\n    A \\== rule,\n    A \\== ui_value,\n    functor(H, A, 1),\n    predicate_property(H, dynamic).\n\n% The values an attribute is allowed to take, where anything says.\nhas_domain(A) :- T =.. [A, _], \\+ \\+ known_value(T), !.\nhas_domain(A) :- \\+ \\+ ui_value(A, _).\n\nknown_attr_value(A, V) :- T =.. [A, V], known_value(T), !.\nknown_attr_value(A, V) :- ui_value(A, V), !.\nknown_attr_value(A, unknown) :- ui_value(A, _), !.   % the \"I don't know\" answer\n\n% The categorical values a rule body tests an attribute against:\n% either attr(const), or attr(X) followed by member(X, [...]).\nconstraint(Body, A, [V]) :-\n    body_goal(Body, G),\n    G =.. [A, V],\n    atom(V),\n    session_attribute(A).\nconstraint(Body, A, Vs) :-\n    body_goal(Body, G),\n    G =.. [A, X],\n    var(X),\n    session_attribute(A),\n    body_goal(Body, member(Y, Vs)),\n    Y == X,\n    is_list(Vs).\n\ntested_value(Body, A, V) :-\n    constraint(Body, A, Vs),\n    member(V, Vs).\n\n% What a rule concludes, one term at a time (unfold/2: boss_infer.pl).\nconcludes_term(Id, C) :-\n    rule_clause(Id, Concl, _, _),\n    unfold(Concl, C).\n\n% ------------------------------------------------------------\n% 1. Certainty factors and identity\n% ------------------------------------------------------------\n\nkb_issue(error, cf_not_number, Id) :-\n    rule_clause(Id, _, CF, _),\n    \\+ number(CF).\nkb_issue(error, cf_out_of_range, Id-CF) :-\n    rule_clause(Id, _, CF, _),\n    number(CF),\n    ( CF < -1 ; CF > 1 ).\nkb_issue(error, id_not_atom, Id) :-\n    rule_clause(Id, _, _, _),\n    \\+ atom(Id).\nkb_issue(error, duplicate_id, Id) :-\n    rule_id(Id),\n    findall(x, rule_clause(Id, _, _, _), Xs),\n    length(Xs, N),\n    N > 1.\n\n% ------------------------------------------------------------\n% 2. Completeness: every rule wired into inference and explanation\n% ------------------------------------------------------------\n\n% Without a level, fires/1 and holds/1 never see the rule.\nkb_issue(error, no_level, Id) :-\n    rule_id(Id),\n    \\+ rule_level(Id, _).\nkb_issue(error, bad_level, Id-L) :-\n    rule_level(Id, L),\n    \\+ member(L, [1, 2, 3]).\nkb_issue(warning, orphan_level, Id) :-\n    rule_level(Id, _),\n    \\+ rule_id(Id).\n\nkb_issue(error, no_text, Id) :-\n    rule_id(Id),\n    \\+ rule_text(Id, _).\nkb_issue(warning, orphan_text, Id) :-\n    rule_text(Id, _),\n    \\+ rule_id(Id).\n\n% A concern with nothing the user can do about it.\nkb_issue(warning, no_action, Id) :-\n    rule_clause(Id, _, CF, _),\n    number(CF),\n    CF < 0,\n    \\+ next_action(Id, _).\nkb_issue(warning, orphan_action, Id) :-\n    next_action(Id, _),\n    \\+ rule_id(Id).\n\n% boss_infer.pl names these rules directly.\nreserved_rule(r10, override).  reserved_rule(r11, override).\nreserved_rule(r21, override).  reserved_rule(r22, ladder).\nreserved_rule(r23, ladder).    reserved_rule(r24, ladder).\nreserved_rule(r25, ladder).\n\nkb_issue(error, reserved_missing, Id) :-\n    reserved_rule(Id, _),\n    \\+ rule_id(Id).\n\n% ------------------------------------------------------------\n% 3. Vocabulary: rules speak only about what the system knows\n% ------------------------------------------------------------\n\nkb_issue(error, undefined_goal, Id-(N/A)) :-\n    rule_clause(Id, _, _, Body),\n    body_goal(Body, G),\n    callable(G),\n    functor(G, N, A),\n    \\+ builtin(N/A),\n    \\+ current_predicate(N/A).\n\n% A value no answer can ever produce: the condition can never hold.\nkb_issue(error, unknown_value, Id-T) :-\n    rule_clause(Id, _, _, Body),\n    tested_value(Body, A, V),\n    has_domain(A),\n    \\+ known_attr_value(A, V),\n    T =.. [A, V].\n\n% The questionnaire offers an answer the knowledge base would reject\n% as unrecognised (boss_derive.pl), e.g. after a fixed fact is removed.\nkb_issue(error, ui_unrecognised, T) :-\n    ui_value(A, V),\n    T =.. [A, V],\n    checked_input(T),\n    \\+ known_value(T).\n\nkb_issue(error, unknown_verdict, Id-V) :-\n    concludes_term(Id, recommendation(V)),\n    \\+ verdict_text(V, _).\n\nkb_issue(warning, gap_unlabelled, Id-G) :-\n    concludes_term(Id, validation_gap(G)),\n    \\+ gap_label(G, _).\n\n% The body asks for a conclusion that no rule draws.\nkb_issue(warning, unsupported_holds, Id-C) :-\n    rule_clause(Id, _, _, Body),\n    body_goal(Body, G),\n    ( G = holds(C) ; G = holds_upto(_, C) ),\n    nonvar(C),\n    \\+ concludes_term(_, C).\n\n% ------------------------------------------------------------\n% 4. Stratification (boss_infer.pl header)\n% A rule may only read conclusions from a level below its own,\n% otherwise holds/1 can re-enter the rule it is proving.\n% ------------------------------------------------------------\n\nreads_level(holds(_), 2).\nreads_level(holds_upto(K, _), K).\nreads_level(core_positive, 2).\nreads_level(weakness(_), 2).\nreads_level(weakness_count(_), 2).\nreads_level(severe_risk(_), 2).\nreads_level(severe_risk_count(_), 2).\nreads_level(absolute_override, 3).\nreads_level(fires(_), 3).\n\nkb_issue(error, stratification, Id-G) :-\n    rule_clause(Id, _, _, Body),\n    rule_level(Id, L),\n    L < 3,\n    body_goal(Body, G),\n    reads_level(G, K),\n    ( var(K) ; K >= L ).\n\n% Level 3 is outside holds/1: a non-verdict drawn there is never read.\nkb_issue(warning, level_unread, Id-C) :-\n    rule_level(Id, 3),\n    concludes_term(Id, C),\n    C \\= recommendation(_).\nkb_issue(warning, verdict_below_3, Id) :-\n    rule_level(Id, L),\n    L < 3,\n    concludes_term(Id, recommendation(_)).\n\n% The SRS 9.1 ladder consults R10, R11, R21 and R23-R25 by name. A new\n% verdict rule is traced and explained, but cannot change the verdict.\nkb_issue(warning, not_in_ladder, Id) :-\n    rule_level(Id, 3),\n    rule_id(Id),\n    \\+ reserved_rule(Id, _).\n\n% ------------------------------------------------------------\n% 5. Consistency: two rules that can fire together and disagree\n% ------------------------------------------------------------\n\n% Attributes that legitimately collect several values at once, and\n% the verdict, whose conflicts the SRS 9.1 ladder resolves.\nmulti_valued(validation_gap).\nmulti_valued(red_flag).\nmulti_valued(recommendation).\n\n% No categorical condition tells the two rules apart. Numeric tests\n% are not compared, so this is a warning, not a proof.\nexclusive(B1, B2) :-\n    constraint(B1, A, V1s),\n    constraint(B2, A, V2s),\n    \\+ ( member(V, V1s), member(V, V2s) ).\n\nkb_issue(warning, conflict, (I1-I2):C1/C2) :-\n    rule_clause(I1, _, _, B1),\n    rule_clause(I2, _, _, B2),\n    I1 @< I2,\n    rule_level(I1, L), rule_level(I2, L),\n    concludes_term(I1, C1),\n    concludes_term(I2, C2),\n    C1 =.. [F, V1],\n    C2 =.. [F, V2],\n    \\+ multi_valued(F),\n    V1 \\== V2,\n    \\+ exclusive(B1, B2).\n\n% ------------------------------------------------------------\n% Plain-language reading of each check, for the editor.\n% ------------------------------------------------------------\n\ncheck_text(cf_not_number,     'Certainty factor is not a number').\ncheck_text(cf_out_of_range,   'Certainty factor is outside -1 .. 1').\ncheck_text(id_not_atom,       'Rule id must be an atom such as r26').\ncheck_text(duplicate_id,      'Two rules share this id').\ncheck_text(no_level,          'No rule_level/2, so the rule can never fire').\ncheck_text(bad_level,         'Rule level must be 1, 2 or 3').\ncheck_text(orphan_level,      'rule_level/2 for a rule that does not exist').\ncheck_text(no_text,           'No rule_text/2, so the rule cannot be explained').\ncheck_text(orphan_text,       'rule_text/2 for a rule that does not exist').\ncheck_text(no_action,         'A concern with no next_action/2 for the user').\ncheck_text(orphan_action,     'next_action/2 for a rule that does not exist').\ncheck_text(reserved_missing,  'boss_infer.pl names this rule directly; it must exist').\ncheck_text(undefined_goal,    'The body calls a predicate the knowledge base does not define').\ncheck_text(unknown_value,     'A value no answer can produce, so the condition never holds').\ncheck_text(ui_unrecognised,   'The questionnaire offers this answer, but the knowledge base no longer recognises it').\ncheck_text(unknown_verdict,   'A verdict with no verdict_text/2').\ncheck_text(gap_unlabelled,    'A validation gap with no gap_label/2').\ncheck_text(unsupported_holds, 'Reads a conclusion that no rule draws').\ncheck_text(stratification,    'Reads conclusions from its own level or above (can loop)').\ncheck_text(level_unread,      'Level 3 is invisible to holds/1, so nothing can use this conclusion').\ncheck_text(verdict_below_3,   'A verdict drawn below level 3 is not a recommendation rule').\ncheck_text(not_in_ladder,     'The SRS 9.1 ladder does not consult this rule; it cannot change the verdict').\ncheck_text(conflict,          'Can fire together with a different conclusion (numeric tests not compared)').\n"};
